<script>
import generalMixin from "../../mixins/general";

export default {
  name: "PerformanceAnalysis",
  mixins: [generalMixin],
  props: ["queries"],

  data() {
    return {
      loading: true,
      loadingText: "Loading\u2026",
      selectedFiscalYear: "",
      fiscalYears: [],
      customFiscalYearInput: "",
      customFiscalYearError: "",
      staffName: "",
      performancePlan: null,
      objectives: [],
      activities: [],
      subActivities: [],
      kpis: [],
      targets: [],
      // Approved goal adjustments for this plan. Only loaded when the plan's
      // adjustmentStatus === "hod-approved". Each item:
      //   { id, adjustmentType: "drop"|"replace"|"add", oldGoalId, supersededById }
      adjustments: [],
      allReviews: {},
      expandedObjectives: {},
      tooltip: {
        show: false,
        text: "",
        x: 0,
        y: 0,
        reviewerLabel: "",
        reviewerColor: "",
        reviewerIcon: "",
      },
      periods: [
        {
          code: "aprilsept",
          label: "Semester 1",
          months: "April \u2013 September",
          shortLabel: "Semester 1 \u00b7 April\u2013September",
        },
        {
          code: "octmarch",
          label: "Semester 2",
          months: "October \u2013 March",
          shortLabel: "Semester 2 \u00b7 October\u2013March",
        },
      ],
      reviewers: [
        {
          code: "self",
          label: "Self",
          icon: "mdi-account-edit",
          color: "#f97316",
        },
        {
          code: "supervisor",
          label: "Supervisor",
          icon: "mdi-clipboard-account",
          color: "#0d9488",
        },
        {
          code: "joint",
          label: "Joint",
          icon: "mdi-handshake",
          color: "#6366f1",
        },
      ],
      selfPeriod1Status: "",
      selfPeriod2Status: "",
      supervisorPeriod1Status: "",
      supervisorPeriod2Status: "",
      jointPeriod1Status: "",
      jointPeriod2Status: "",
      competencies: [],
    };
  },

  computed: {
    reviewCompleted() {
      return (
        this.selfPeriod1Status === "submitted" &&
        this.selfPeriod2Status === "submitted" &&
        this.supervisorPeriod1Status === "submitted" &&
        this.supervisorPeriod2Status === "submitted" &&
        this.jointPeriod1Status === "submitted" &&
        this.jointPeriod2Status === "submitted"
      );
    },
    allKpis() {
      const result = [];
      for (const act of this.activities) {
        result.push(...this.getKpis(act.id));
        for (const sub of this.getSubActivities(act.id))
          result.push(...this.getKpis(sub.id));
      }
      return result;
    },
    // True only when the plan's mid-year goal-adjustment workflow has been
    // approved by HOD. Drives the "Adjusted Plan" chip in the hero and is
    // implicit in goalAppliesIn (lifecycleStatus stays "original-active" on
    // every goal until adjustments are loaded).
    isAdjustmentApplied() {
      return this.performancePlan?.adjustmentStatus === "hod-approved";
    },

    // Workplan joint avg = sum(joint KPI scores) / total KPIs that applied in
    // this period. After a HOD-approved adjustment, S1 excludes added-at-midyear
    // and S2 excludes dropped originals — so each semester divides by the
    // count of goals that actually existed during that semester.
    workplanJointAvg() {
      return (periodCode) => {
        const periodKpis = this.allKpisForPeriod(periodCode);
        if (!periodKpis.length) return null;
        const scores = periodKpis
          .map((k) => this.getReview(k.id, periodCode, "joint"))
          .filter((r) => r && r.score)
          .map((r) => r.score);
        if (!scores.length) return null;
        return scores.reduce((a, b) => a + b, 0) / periodKpis.length;
      };
    },

    // Competency avg for any reviewer (for reference display in cards)
    competencyAvgByReviewer() {
      return (periodCode, reviewerCode) => {
        if (!this.competencies.length) return null;
        const scores = this.competencies
          .map((comp) => this.getReview(comp.id, periodCode, reviewerCode))
          .filter((r) => r && r.score)
          .map((r) => r.score);
        if (!scores.length) return null;
        return scores.reduce((a, b) => a + b, 0) / this.competencies.length;
      };
    },

    // Competency joint avg = sum(joint competency scores) / total competencies
    competencyJointAvg() {
      return (periodCode) => {
        if (!this.competencies.length) return null;
        const scores = this.competencies
          .map((comp) => this.getReview(comp.id, periodCode, "joint"))
          .filter((r) => r && r.score)
          .map((r) => r.score);
        if (!scores.length) return null;
        return scores.reduce((a, b) => a + b, 0) / this.competencies.length;
      };
    },

    // Semester score = [workplan joint avg + competency joint avg] / 2
    semesterScore() {
      return (periodCode) => {
        const wp = this.workplanJointAvg(periodCode);
        const comp = this.competencyJointAvg(periodCode);
        if (wp === null && comp === null) return null;
        if (wp === null) return comp;
        if (comp === null) return wp;
        return (wp + comp) / 2;
      };
    },

    // Final overall = [Semester 1 + Semester 2] / 2
    overallAverage() {
      const s1 = this.semesterScore("aprilsept");
      const s2 = this.semesterScore("octmarch");
      if (s1 === null && s2 === null) return null;
      if (s1 === null) return s2;
      if (s2 === null) return s1;
      return (s1 + s2) / 2;
    },
  },

  async mounted() {
    await this.$nextTick();
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (v) => {
        if (!v) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        resolve();
      }, 15000);
    });
    try {
      let fy = await fetch("/site/leave/getFinancialYear");
      fy = await fy.json();
      this.selectedFiscalYear = fy.year;
      this.generateFiscalYears(fy.year);
    } catch (e) {
      console.error(e);
    }
    await this.initialize();
  },

  methods: {
    circularColor(score) {
      if (score >= 3.5) return "#059669"; // excellent
      if (score >= 2.5) return "#0d9488"; // good
      if (score >= 1.5) return "#f97316"; // fair
      return "#ef4444"; // poor
    },
    overallProgressBarColor(score) {
      if (score >= 3.5) return "#059669"; // excellent
      if (score >= 2.5) return "#0d9488"; // good
      if (score >= 1.5) return "#f97316"; // fair
      return "#ef4444"; // poor
    },
    showTooltip(event, text, reviewer) {
      if (!text || text.length <= 80) return;
      const rect = event.target.getBoundingClientRect();
      const scrollY = window.scrollY || document.documentElement.scrollTop;
      const scrollX = window.scrollX || document.documentElement.scrollLeft;
      let x = rect.left + scrollX;
      let y = rect.top + scrollY - 8; // appear above the element
      // Keep within viewport horizontally
      if (x + 300 > window.innerWidth + scrollX)
        x = window.innerWidth + scrollX - 316;
      this.tooltip = {
        show: true,
        text,
        x,
        y,
        reviewerLabel: reviewer.label,
        reviewerColor: reviewer.color,
        reviewerIcon: reviewer.icon,
      };
    },
    hideTooltip() {
      this.tooltip.show = false;
    },

    generateFiscalYears(currentFY) {
      this.fiscalYears = [];
      const currentYear = parseInt(currentFY.split("/")[0]);
      for (let i = 4; i >= 0; i--) {
        const start = currentYear - i;
        this.fiscalYears.push(`${start}/${start + 1}`);
      }
    },

    async switchFiscalYear(yr) {
      this.selectedFiscalYear = yr;
      this.customFiscalYearInput = "";
      this.customFiscalYearError = "";
      this.performancePlan = null;
      this.objectives = [];
      this.activities = [];
      this.subActivities = [];
      this.kpis = [];
      this.targets = [];
      this.allReviews = {};
      this.competencies = [];
      await this.initialize();
    },

    applyCustomFiscalYear() {
      const val = this.customFiscalYearInput.trim();
      if (!val) {
        this.customFiscalYearError = "";
        return;
      }
      const valid = /^\d{4}\/\d{4}$/.test(val);
      if (!valid) {
        this.customFiscalYearError = "Format: YYYY/YYYY";
        return;
      }
      const [start, end] = val.split("/").map(Number);
      if (end !== start + 1) {
        this.customFiscalYearError = "End year must be start + 1";
        return;
      }
      this.customFiscalYearError = "";
      this.switchFiscalYear(val);
    },

    // ── Init ─────────────────────────────────────────────────────────────
    async initialize() {
      this.loading = true;
      try {
        this.loadingText = "Loading staff profile\u2026";
        await this.loadStaffName();
        this.loadingText = "Loading performance plan\u2026";
        await this.loadPerformancePlan();
        if (this.performancePlan) {
          this.loadingText = "Loading objectives and KPIs\u2026";
          await this.loadAllData();
          this.loadingText = "Loading all reviews\u2026";
          await this.loadAllReviews();
          if (this.objectives.length) {
            this.$set(this.expandedObjectives, this.objectives[0].id, true);
          }
        }
      } catch (e) {
        console.error("Init error:", e);
      } finally {
        this.loading = false;
      }
    },

    async loadStaffName() {
      const id = this.queries.practitioner;
      if (!id) return;
      try {
        const r = await fetch(`/fhir/Practitioner/${id}`);
        const p = await r.json();
        const name = p.name?.[0];
        if (name)
          this.staffName = [...(name.given || []), name.family]
            .filter(Boolean)
            .join(" ");
      } catch (e) {
        console.error(e);
      }
    },

    async loadPerformancePlan() {
      const practitioner = this.queries.practitioner;
      if (!practitioner) return;
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-plan-profile",
        practitioner: `Practitioner/${practitioner}`,
        fiscalyear: this.selectedFiscalYear,
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.selfPeriod1Status = b.entry[0].resource.extension.find((ext) => {
        return (
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/self-period1-annual-review-status"
        );
      })?.valueCoding?.code;
      this.selfPeriod2Status = b.entry[0].resource.extension.find((ext) => {
        return (
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/self-period2-annual-review-status"
        );
      })?.valueCoding?.code;
      this.supervisorPeriod1Status = b.entry[0].resource.extension.find(
        (ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/supervisor-period1-annual-review-status"
          );
        },
      )?.valueCoding?.code;
      this.supervisorPeriod2Status = b.entry[0].resource.extension.find(
        (ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/supervisor-period2-annual-review-status"
          );
        },
      )?.valueCoding?.code;
      this.jointPeriod1Status = b.entry[0].resource.extension.find((ext) => {
        return (
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/joint-period1-annual-review-status"
        );
      })?.valueCoding?.code;
      this.jointPeriod2Status = b.entry[0].resource.extension.find((ext) => {
        return (
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/joint-period2-annual-review-status"
        );
      })?.valueCoding?.code;
      if (b.entry?.length > 0) {
        const res = b.entry[0].resource;
        this.performancePlan = {
          id: res.id,
          name: this.ext(res, "ihris-basic-name")?.valueString || "",
          // Captures whether the mid-year goal-adjustment workflow has been
          // approved. Only "hod-approved" means the adjustments have been
          // applied — anything else and Semester 2 stays on original goals.
          adjustmentStatus:
            this.ext(res, "goal-adjustment-status")?.valueCoding?.code || null,
        };
      }
    },

    async loadAllData() {
      await this.loadObjectives();
      await this.loadActivities();
      await this.loadSubActivities();
      await this.loadKpis();
      await this.loadTargets();
      await this.loadCompetencies();
      await this.loadAdjustments();
    },

    // Loads HOD-approved goal adjustments for the plan and annotates the goal
    // arrays with `adjustmentType` (drop/replace/add) and `replacement` (the
    // new goal of a replace pair).
    //
    // ⚠ INVARIANT: This function mutates this.objectives / this.activities /
    // this.subActivities / this.kpis / this.targets in place. Unlike
    // performance-review.vue, we DO NOT remove replacement goals from the
    // arrays — analysis displays both periods side-by-side, so the old goal
    // must remain visible for the S1 column and the new replacement must
    // remain visible for the S2 column.
    //
    // No filtering is applied for non-applied plans (adjustmentStatus !==
    // "hod-approved") — those goals retain their original lifecycle. Score
    // computeds use `goalAppliesIn(goal, periodCode)` to decide which goals
    // contribute to which semester's totals.
    async loadAdjustments() {
      if (!this.performancePlan) {
        this.adjustments = [];
        return;
      }
      if (this.performancePlan.adjustmentStatus !== "hod-approved") {
        this.adjustments = [];
        return;
      }
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/goal-adjustment-profile",
          performanceplan: `Basic/${this.performancePlan.id}`,
          _count: 500,
        });
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        this.adjustments = (b.entry || []).map((e) => {
          const res = e.resource;
          return {
            id: res.id,
            adjustmentType:
              this.ext(res, "goal-adjustment-type")?.valueCoding?.code || "",
            oldGoalId:
              this.ext(res, "old-goal")?.valueReference?.reference?.split(
                "/",
              )[1] || null,
            supersededById:
              this.ext(
                res,
                "superseded-by-goal",
              )?.valueReference?.reference?.split("/")[1] || null,
          };
        });

        // Annotate every goal: tag drops/replaces, attach `replacement`
        // pointer where applicable. We do NOT re-parent or remove anything —
        // the analysis view needs all goals visible side-by-side.
        const goals = [
          "objectives",
          "activities",
          "subActivities",
          "kpis",
          "targets",
        ];
        for (const goal of goals) {
          for (const item of this[goal]) {
            const adjustment = this.adjustments.find(
              (adj) => adj.oldGoalId === item.id,
            );
            if (adjustment) {
              item.adjustmentType = adjustment.adjustmentType;
              if (adjustment.adjustmentType === "replace") {
                const replacement = this[goal].find(
                  (obj) => obj.id == adjustment.supersededById,
                );
                if (replacement) {
                  item.replacement = replacement;
                } else {
                  console.warn(
                    `[loadAdjustments] ${goal}: replacement goal ` +
                      `"${adjustment.supersededById}" referenced by adjustment ` +
                      `"${adjustment.id}" was not found in the loaded array.`,
                  );
                }
              }
            } else if (item.lifecycleStatus === "original-dropped") {
              // Lifecycle says dropped but no adjustment record found — still
              // honour the lifecycle (defensive — covers any data inconsistency).
              item.adjustmentType = "drop";
            }
          }
        }
      } catch (e) {
        console.error("loadAdjustments error", e);
        this.adjustments = [];
      }
    },

    async loadObjectives() {
      if (!this.performancePlan) return;
      const r = await fetch(
        `/fhir/Basic?${new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-objective-profile",
          performanceplan: `Basic/${this.performancePlan.id}`,
        })}`,
      );
      const b = await r.json();
      this.objectives = b.entry
        ? b.entry.map((e) => this.extractBasicData(e.resource))
        : [];
    },

    async loadActivities() {
      if (!this.objectives.length) {
        this.activities = [];
        return;
      }
      const r = await fetch(
        `/fhir/Basic?${new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-activity-profile",
          parent: this.objectives.map((o) => o.id).join(","),
        })}`,
      );
      const b = await r.json();
      this.activities = b.entry
        ? b.entry.map((e) => this.extractBasicData(e.resource))
        : [];
    },

    async loadSubActivities() {
      if (!this.activities.length) {
        this.subActivities = [];
        return;
      }
      const r = await fetch(
        `/fhir/Basic?${new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-subactivity-profile",
          parent: this.activities.map((a) => a.id).join(","),
        })}`,
      );
      const b = await r.json();
      this.subActivities = b.entry
        ? b.entry.map((e) => this.extractBasicData(e.resource))
        : [];
    },

    async loadKpis() {
      if (!this.activities.length && !this.subActivities.length) {
        this.kpis = [];
        return;
      }
      const ids = [
        ...this.activities.map((a) => a.id),
        ...this.subActivities.map((s) => s.id),
      ].join(",");
      const params = new URLSearchParams();
      params.append(
        "_profile",
        "http://ihris.org/fhir/StructureDefinition/performance-kpi-profile",
      );
      params.append("parent", ids);
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.kpis = b.entry
        ? b.entry.map((e) => this.extractBasicData(e.resource))
        : [];
    },

    async loadTargets() {
      if (!this.kpis.length) {
        this.targets = [];
        return;
      }
      const params = new URLSearchParams();
      params.append(
        "_profile",
        "http://ihris.org/fhir/StructureDefinition/performance-target-profile",
      );
      params.append("parent", this.kpis.map((k) => k.id).join(","));
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.targets = b.entry
        ? b.entry.map((e) => this.extractBasicData(e.resource))
        : [];
    },

    async loadAllReviews() {
      if (!this.performancePlan) return;
      try {
        const params = new URLSearchParams();
        params.append(
          "_profile",
          "http://ihris.org/fhir/StructureDefinition/performance-review-profile",
        );
        params.append("_count", 200);
        params.append("performanceplan", `Basic/${this.performancePlan.id}`);
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();

        if (b.entry) {
          const reviews = {};
          for (const e of b.entry) {
            const res = e.resource;
            const kpiId =
              this.ext(res, "parent")?.valueReference?.reference?.split(
                "/",
              )[1] || null;
            const reviewer =
              this.ext(res, "performance-reviewer")?.valueCoding?.code || null;
            const period =
              this.ext(res, "performance-review-period")?.valueCoding?.code ||
              null;
            const score = this.ext(res, "score")?.valueInteger || null;
            const comments = this.ext(res, "description")?.valueString || "";
            if (kpiId && reviewer && period && score) {
              reviews[`${kpiId}_${period}_${reviewer}`] = { score, comments };
            }
          }
          this.allReviews = reviews;
        }
      } catch (e) {
        console.error("Error loading reviews:", e);
      }
    },

    async loadCompetencies() {
      if (!this.loggedInStaff?.grade) {
        this.competencies = [];
        return;
      }
      try {
        const r = await fetch(
          `/fhir/Basic?${new URLSearchParams({
            _profile:
              "http://ihris.org/fhir/StructureDefinition/competency-profile",
            salarygrade: "grade" + this.loggedInStaff.grade,
            _count: 200,
          })}`,
        );
        const b = await r.json();
        this.competencies = (b.entry || []).map((e) => {
          const res = e.resource;
          return {
            id: res.id,
            name: this.ext(res, "ihris-basic-name")?.valueString || "",
            description: this.ext(res, "description")?.valueString || "",
            requirements:
              res.extension
                ?.filter((ex) => ex.url.includes("competency-requirements"))
                .map((ex) => ex.valueString)
                .filter(Boolean) || [],
          };
        });
      } catch (e) {
        console.error("Error loading competencies:", e);
        this.competencies = [];
      }
    },

    // ── Extractors ───────────────────────────────────────────────────────
    ext(resource, url) {
      return resource.extension?.find((e) => e.url.includes(url));
    },
    extractBasicData(r) {
      return {
        id: r.id,
        name: this.ext(r, "ihris-basic-name")?.valueString || "",
        description: this.ext(r, "description")?.valueString || "",
        parentId:
          this.ext(r, "parent")?.valueReference?.reference?.split("/")[1] ||
          null,
        // Goal lifecycle — drives which periods this goal applies to.
        // Falls back to "original-active" for legacy goals predating the
        // adjustment workflow (extension absent).
        lifecycleStatus:
          this.ext(r, "goal-lifecycle-status")?.valueCoding?.code ||
          "original-active",
      };
    },

    // ── Data helpers ─────────────────────────────────────────────────────
    getActivities(objId) {
      return this.activities.filter((a) => a.parentId === objId);
    },
    getSubActivities(actId) {
      return this.subActivities.filter((s) => s.parentId === actId);
    },
    getKpis(parentId) {
      return this.kpis.filter((k) => k.parentId === parentId);
    },
    getTargetForKpi(kpiId) {
      return this.targets.find((t) => t.parentId === kpiId) || null;
    },
    getReview(kpiId, period, reviewer) {
      return this.allReviews[`${kpiId}_${period}_${reviewer}`] || null;
    },

    // Returns true when this goal contributed to the given period's plan.
    //   Semester 1 (aprilsept): all goals EXCEPT those added at mid-year.
    //   Semester 2 (octmarch):  all goals EXCEPT those that were dropped.
    // For non-approved adjustment plans, every goal applies to both periods
    // (lifecycleStatus stays "original-active" so neither branch excludes).
    goalAppliesIn(goal, periodCode) {
      if (!goal) return false;
      if (periodCode === "aprilsept") {
        return goal.lifecycleStatus !== "added-at-midyear";
      }
      // Semester 2: exclude originals that were dropped or replaced.
      // "original-dropped" lifecycle covers both drop and replace cases.
      if (goal.adjustmentType === "drop") return false;
      if (goal.lifecycleStatus === "original-dropped") return false;
      return true;
    },

    // KPIs that count toward this period's totals. Built from this.allKpis
    // (every KPI in memory) filtered by goalAppliesIn.
    allKpisForPeriod(periodCode) {
      return this.allKpis.filter((k) => this.goalAppliesIn(k, periodCode));
    },

    // ── Stats helpers ────────────────────────────────────────────────────
    // Per-reviewer card chip average. Filters to KPIs that applied in this
    // period so adjusted plans don't accidentally pick up stale scores from
    // out-of-period goals.
    periodAvg(periodCode, reviewerCode) {
      const scores = this.allKpisForPeriod(periodCode)
        .map((k) => this.getReview(k.id, periodCode, reviewerCode))
        .filter((r) => r && r.score)
        .map((r) => r.score);
      if (!scores.length) return null;
      return scores.reduce((a, b) => a + b, 0) / scores.length;
    },
    objKpiCount(objId) {
      let n = 0;
      for (const act of this.getActivities(objId)) {
        n += this.getKpis(act.id).length;
        for (const sub of this.getSubActivities(act.id))
          n += this.getKpis(sub.id).length;
      }
      return n;
    },
    objAvgScore(objId) {
      const kpis = [];
      for (const act of this.getActivities(objId)) {
        kpis.push(...this.getKpis(act.id));
        for (const sub of this.getSubActivities(act.id))
          kpis.push(...this.getKpis(sub.id));
      }
      const scores = kpis
        .flatMap((k) =>
          this.periods.flatMap((p) =>
            // Skip period/KPI combinations where the KPI didn't apply —
            // protects against stale scores on goals that were dropped or
            // newly-added at mid-year.
            this.goalAppliesIn(k, p.code)
              ? this.reviewers.map((rv) =>
                  this.getReview(k.id, p.code, rv.code),
                )
              : [],
          ),
        )
        .filter((r) => r && r.score)
        .map((r) => r.score);
      if (!scores.length) return null;
      return scores.reduce((a, b) => a + b, 0) / scores.length;
    },

    compAvgScore(compId) {
      const scores = this.periods
        .map((p) => this.getReview(compId, p.code, "joint"))
        .filter((r) => r && r.score)
        .map((r) => r.score);
      if (!scores.length) return null;
      return scores.reduce((a, b) => a + b, 0) / scores.length;
    },

    // ── Score helpers ────────────────────────────────────────────────────
    scoreClass(score) {
      if (score === null || score === undefined) return "none";
      if (score >= 3.5) return "excellent";
      if (score >= 2.5) return "good";
      if (score >= 1.5) return "fair";
      return "poor";
    },
    scoreLabel(score) {
      if (score === null || score === undefined) return "\u2014";
      if (score >= 3.5) return "Exceeded Expectations";
      if (score >= 2.5) return "Fully Met";
      if (score >= 1.5) return "Partially Met";
      return "Did Not Meet";
    },
    scoreLabelShort(score) {
      if (!score) return "\u2014";
      if (score >= 3.5) return "Exceeded";
      if (score >= 2.5) return "Fully Met";
      if (score >= 1.5) return "Partial";
      return "Did Not Meet";
    },

    toggleObjective(id) {
      this.$set(this.expandedObjectives, id, !this.expandedObjectives[id]);
    },

    headerBg(index) {
      const gradients = [
        "linear-gradient(135deg, #1e3a5f 0%, #1e40af 100%)",
        "linear-gradient(135deg, #0f4c5c 0%, #0e7490 100%)",
        "linear-gradient(135deg, #14532d 0%, #166534 100%)",
        "linear-gradient(135deg, #3b0764 0%, #6d28d9 100%)",
        "linear-gradient(135deg, #7c2d12 0%, #9a3412 100%)",
        "linear-gradient(135deg, #7f1d1d 0%, #991b1b 100%)",
      ];
      return gradients[index % gradients.length];
    },

    scoreStyle(score) {
      const map = {
        4: {
          background: "#ecfdf5",
          border: "1.5px solid #a7f3d0",
          color: "#059669",
        },
        3: {
          background: "#f0fdfa",
          border: "1.5px solid #99f6e4",
          color: "#0d9488",
        },
        2: {
          background: "#fff7ed",
          border: "1.5px solid #fed7aa",
          color: "#f97316",
        },
        1: {
          background: "#fef2f2",
          border: "1.5px solid #fecaca",
          color: "#ef4444",
        },
      };
      return (
        map[score] || {
          background: "#fafaf8",
          border: "1.5px solid #f5f5f4",
          color: "#a8a29e",
        }
      );
    },
  },
};
</script>

