.pra-root {
  min-height: 100vh;
  background: #f5f4f2;
  font-family: "Sora", sans-serif;
}

/* ── TOOLTIP ─────────────────────────────────────────────────────── */
.pra-tooltip-box {
  position: absolute;
  z-index: 9999;
  max-width: 300px;
  background: #1c1917;
  color: rgba(255, 255, 255, 0.92);
  border-radius: 10px;
  padding: 10px 14px 12px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.28);
  pointer-events: none;
  transform: translateY(-100%) translateY(-10px);
  animation: pra-tooltip-in 0.12s ease;
}
@keyframes pra-tooltip-in {
  from {
    opacity: 0;
    transform: translateY(-100%) translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(-100%) translateY(-10px);
  }
}
.pra-tooltip-box__reviewer {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: rgba(255, 255, 255, 0.45);
  margin-bottom: 6px;
}
.pra-tooltip-box__text {
  font-size: 12px;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.88);
  white-space: pre-wrap;
}

/* ── HERO ────────────────────────────────────────────────────────── */
.pra-hero {
  position: relative;
  background: linear-gradient(135deg, #0c1f3f 0%, #0f2d5e 50%, #1a3a6e 100%);
  overflow: hidden;
}
.pra-hero__grid {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(
      rgba(255, 255, 255, 0.03) 1px,
      transparent 1px
    ),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 32px 32px;
  pointer-events: none;
}
.pra-hero__orb {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}
.pra-hero__orb--1 {
  width: 400px;
  height: 400px;
  top: -150px;
  right: -80px;
  background: radial-gradient(
    circle,
    rgba(99, 102, 241, 0.14) 0%,
    transparent 70%
  );
}
.pra-hero__orb--2 {
  width: 300px;
  height: 300px;
  bottom: -120px;
  left: 10%;
  background: radial-gradient(
    circle,
    rgba(13, 148, 136, 0.12) 0%,
    transparent 70%
  );
}
.pra-hero__inner {
  position: relative;
  z-index: 1;
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 32px 44px;
}
.pra-hero__breadcrumb {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.5);
  margin-bottom: 32px;
  font-weight: 500;
}
.pra-hero__breadcrumb-link {
  cursor: pointer;
  transition: color 0.15s;
}
.pra-hero__breadcrumb-link:hover {
  color: rgba(255, 255, 255, 0.8);
}
.pra-hero__breadcrumb-active {
  color: rgba(255, 255, 255, 0.8);
}
.pra-hero__content {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 24px;
}
.pra-hero__eyebrow {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  font-weight: 600;
  color: #5eead4;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 10px;
}
.pra-hero__eyebrow-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #5eead4;
  flex-shrink: 0;
}
.pra-hero__title {
  font-size: 38px;
  font-weight: 800;
  color: white;
  letter-spacing: -0.04em;
  line-height: 1.1;
  margin: 0 0 12px;
}
.pra-hero__title-loading {
  color: rgba(255, 255, 255, 0.3);
  font-size: 28px;
}
.pra-hero__subtitle {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.5);
  line-height: 1.6;
  margin: 0;
  max-width: 460px;
}
.pra-hero__right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  min-height: 170px;
}
.pra-year-tabs {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 3px;
  gap: 2px;
  margin-top: auto;
}
.pra-year-tab {
  padding: 5px 12px;
  border-radius: 7px;
  border: none;
  background: transparent;
  color: rgba(255, 255, 255, 0.5);
  font-size: 11px;
  cursor: pointer;
  font-family: "JetBrains Mono", monospace;
  transition: all 0.15s;
  letter-spacing: -0.02em;
}
.pra-year-tab:hover {
  color: #a8a29e;
}
.pra-year-tab--active {
  background: #6366f1 !important;
  color: white !important;
}
.pra-year-custom {
  display: flex;
  flex-direction: column;
  position: relative;
}
.pra-year-custom__input {
  padding: 5px 10px;
  border-radius: 7px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.7);
  font-size: 11px;
  font-family: "JetBrains Mono", monospace;
  width: 90px;
  outline: none;
  transition: all 0.15s;
}
.pra-year-custom__input::placeholder {
  color: rgba(255, 255, 255, 0.3);
}
.pra-year-custom__input:focus {
  border-color: rgba(99, 102, 241, 0.5);
  background: rgba(99, 102, 241, 0.08);
  color: white;
}
.pra-year-custom__input--active {
  background: #6366f1 !important;
  color: white !important;
  border-color: #6366f1 !important;
}
.pra-year-custom__input--error {
  border-color: #ef4444 !important;
}
.pra-year-custom__err {
  font-size: 9px;
  color: #f87171;
  margin-top: 2px;
  position: absolute;
  top: 100%;
  right: 0;
  white-space: nowrap;
}
.pra-hero__overall-badge {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 16px;
  padding: 16px 22px;
  text-align: center;
  min-width: 130px;
}
.pra-hero__overall-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: rgba(255, 255, 255, 0.4);
  margin-bottom: 6px;
}
.pra-hero__overall-score {
  font-family: "JetBrains Mono", monospace;
  font-size: 36px;
  font-weight: 700;
  line-height: 1;
  margin-bottom: 4px;
}
.pra-hero__overall-score--excellent {
  color: #6ee7b7;
}
.pra-hero__overall-score--good {
  color: #5eead4;
}
.pra-hero__overall-score--fair {
  color: #fdba74;
}
.pra-hero__overall-score--poor {
  color: #fca5a5;
}
.pra-hero__overall-score--none {
  color: rgba(255, 255, 255, 0.3);
}
.pra-hero__overall-rating {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.5);
  font-weight: 500;
}

/* Competency matrix + body container alignment */
.pra-objective__body,
.pra-obj-body {
  padding: 12px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pra-matrix {
  border: 1px solid #f0f0ef;
  border-radius: 10px;
  overflow: hidden;
  background: white;
}
.pra-matrix__header-row,
.pra-matrix__data-row {
  display: grid;
  grid-template-columns: 160px 1fr 1fr;
}
.pra-matrix__header-row {
  background: #fafaf8;
  border-bottom: 1px solid #f0f0ef;
}
.pra-matrix__data-row {
  border-top: 1px solid #f5f5f4;
}
.pra-matrix__kpi-col {
  padding: 10px 12px;
  border-right: 1px solid #f0f0ef;
  display: flex;
  align-items: center;
}
.pra-matrix__kpi-name {
  font-size: 12px;
  font-weight: 700;
  color: #44403c;
}
.pra-matrix__period-group {
  border-right: 1px solid #f0f0ef;
}
.pra-matrix__period-group:last-child {
  border-right: none;
}
.pra-matrix__period-label {
  padding: 8px 10px 6px;
  border-bottom: 1px solid #f0f0ef;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.pra-matrix__period-label--aprilsept {
  background: #fff7ed;
  color: #f97316;
  border-bottom-color: #fed7aa;
}
.pra-matrix__period-label--octmarch {
  background: #eef2ff;
  color: #6366f1;
  border-bottom-color: #c7d2fe;
}
.pra-matrix__reviewer-cols {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.pra-matrix__reviewer-col,
.pra-matrix__cell {
  padding: 10px 10px;
  border-right: 1px solid #f5f5f4;
}
.pra-matrix__reviewer-col:last-child,
.pra-matrix__cell:last-child {
  border-right: none;
}
.pra-matrix__reviewer-col {
  font-size: 10px;
  font-weight: 700;
  color: #78716c;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  display: flex;
  align-items: center;
  gap: 4px;
}

@media (max-width: 800px) {
  .pra-hero__right {
    min-height: 0;
    justify-content: flex-start;
    align-items: flex-start;
    width: 100%;
  }
  .pra-year-tabs {
    justify-content: flex-start;
    width: 100%;
  }
  .pra-matrix__header-row,
  .pra-matrix__data-row {
    grid-template-columns: 1fr;
  }
  .pra-matrix__kpi-col {
    border-right: none;
    border-bottom: 1px solid #f0f0ef;
  }
  .pra-matrix__period-group {
    border-right: none;
    border-top: 1px solid #f5f5f4;
  }
}

/* ── LOADING ─────────────────────────────────────────────────────── */
.pra-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 80px;
}
.pra-loading__spinner {
  width: 36px;
  height: 36px;
  border: 3px solid #e7e5e4;
  border-top-color: #6366f1;
  border-radius: 50%;
  animation: pra-spin 0.8s linear infinite;
}
@keyframes pra-spin {
  to {
    transform: rotate(360deg);
  }
}
.pra-loading__text {
  font-size: 14px;
  color: #a8a29e;
  font-weight: 500;
}

/* ── BODY ────────────────────────────────────────────────────────── */
.pra-body {
  max-width: 1200px;
  margin: 0 auto;
  padding: 40px 32px 80px;
  display: flex;
  flex-direction: column;
  gap: 44px;
}
.pra-section__head {
  margin-bottom: 22px;
}
.pra-section__title {
  font-size: 20px;
  font-weight: 800;
  color: #1c1917;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}
.pra-section__sub {
  font-size: 13px;
  color: #a8a29e;
}

/* ── PERIOD CARDS ────────────────────────────────────────────────── */
.pra-period-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}
@media (max-width: 750px) {
  .pra-period-grid {
    grid-template-columns: 1fr;
  }
}
.pra-period-card {
  background: white;
  border-radius: 20px;
  border: 1.5px solid #e7e5e4;
  overflow: hidden;
}
.pra-period-card__accent {
  height: 4px;
}
.pra-period-card__accent--aprilsept {
  background: linear-gradient(90deg, #f97316, #fb923c);
}
.pra-period-card__accent--octmarch {
  background: linear-gradient(90deg, #6366f1, #818cf8);
}
.pra-period-card__header {
  padding: 20px 24px 16px;
  border-bottom: 1px solid #f5f5f4;
}
.pra-period-card__title {
  font-size: 17px;
  font-weight: 800;
  color: #1c1917;
  letter-spacing: -0.02em;
}
.pra-period-card__sub {
  font-size: 12px;
  color: #a8a29e;
  margin-top: 2px;
}
.pra-period-card__scores {
  padding: 18px 24px 22px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.pra-reviewer-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
.pra-reviewer-dot--self {
  background: #f97316;
}
.pra-reviewer-dot--supervisor {
  background: #0d9488;
}
.pra-reviewer-dot--joint {
  background: #6366f1;
}
.pra-reviewer-dot--sm {
  width: 6px;
  height: 6px;
}
.pra-reviewer-row__pending {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: #d6d3d1;
  font-style: italic;
}
.pra-period-card__divider {
  height: 1px;
  background: #f5f5f4;
  margin: 4px 0;
}
.pra-period-avg {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.pra-period-avg--empty {
  flex-direction: row;
  justify-content: center;
  gap: 8px;
  color: #d6d3d1;
  font-size: 12px;
  font-style: italic;
  padding: 8px 0;
}
.pra-period-avg__label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #a8a29e;
}
.pra-period-avg__right {
  display: flex;
  align-items: center;
  gap: 14px;
}
.pra-period-avg__ring {
  position: relative;
  width: 56px;
  height: 56px;
  flex-shrink: 0;
}
.pra-ring-value {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-family: "JetBrains Mono", monospace;
  font-size: 13px;
  font-weight: 700;
  color: #1c1917;
}
.pra-period-avg__meta {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.pra-period-avg__rating {
  font-size: 13px;
  font-weight: 700;
}
.pra-period-avg__kpis {
  font-size: 11px;
  color: #a8a29e;
}

/* ── ANNUAL BAR ──────────────────────────────────────────────────── */
.pra-annual-bar {
  background: white;
  border: 1.5px solid #e7e5e4;
  border-radius: 16px;
  padding: 18px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.pra-annual-bar__left {
  display: flex;
  align-items: center;
  gap: 10px;
}
.pra-annual-bar__label {
  font-size: 14px;
  font-weight: 700;
  color: #1c1917;
}
.pra-annual-bar__badge {
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 20px;
}
.pra-annual-bar__badge--excellent {
  background: #ecfdf5;
  color: #059669;
}
.pra-annual-bar__badge--good {
  background: #f0fdfa;
  color: #0d9488;
}
.pra-annual-bar__badge--fair {
  background: #fff7ed;
  color: #f97316;
}
.pra-annual-bar__badge--poor {
  background: #fef2f2;
  color: #ef4444;
}
.pra-annual-bar__badge--none {
  background: #fafaf8;
  color: #a8a29e;
}
.pra-annual-bar__right {
  display: flex;
  align-items: center;
  gap: 16px;
  flex: 1;
  max-width: 500px;
}
.pra-annual-score {
  font-family: "JetBrains Mono", monospace;
  font-size: 15px;
  font-weight: 700;
  white-space: nowrap;
}

/* ── OBJECTIVES ──────────────────────────────────────────────────── */
.pra-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 60px;
  background: white;
  border-radius: 16px;
  border: 1.5px solid #e7e5e4;
  text-align: center;
}
.pra-empty h3 {
  font-size: 16px;
  font-weight: 700;
  color: #1c1917;
  margin: 0;
}
.pra-empty p {
  font-size: 13px;
  color: #a8a29e;
  margin: 0;
}
.pra-objectives {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.pra-objective {
  border-radius: 18px;
  overflow: hidden;
  border: 1.5px solid #e7e5e4;
  background: white;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.04);
}
/* Header receives background via :style="{ background: headerBg(oi) }" */
.pra-obj-header {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px 20px;
  border: none;
  cursor: pointer;
  font-family: "Sora", sans-serif;
  text-align: left;
  transition: filter 0.15s;
}
.pra-obj-header:hover {
  filter: brightness(1.08);
}
/* Translucent number badge — mirrors pvr-objective__num */
.pra-obj-header__num {
  font-family: "JetBrains Mono", monospace;
  font-size: 12px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.5);
  background: rgba(255, 255, 255, 0.12);
  padding: 3px 8px;
  border-radius: 6px;
  flex-shrink: 0;
}
.pra-obj-header__info {
  flex: 1;
  min-width: 0;
}
.pra-obj-header__title {
  font-size: 15px;
  font-weight: 700;
  color: white;
  letter-spacing: -0.01em;
}
.pra-obj-header__meta {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.6);
  margin-top: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pra-obj-header__stats {
  display: flex;
  gap: 14px;
  flex-shrink: 0;
}
.pra-obj-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.pra-obj-stat__num {
  font-family: "JetBrains Mono", monospace;
  font-size: 16px;
  font-weight: 800;
  color: white;
}
.pra-obj-stat__num--avg {
  color: rgba(255, 255, 255, 0.85);
}
.pra-obj-stat__label {
  font-size: 10px;
  color: rgba(255, 255, 255, 0.5);
  font-weight: 500;
}
.pra-obj-chevron {
  transition: transform 0.25s !important;
  flex-shrink: 0;
}
.pra-obj-chevron--open {
  transform: rotate(180deg) !important;
}
.pra-obj-body {
  padding: 12px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── ACTIVITY GROUPS ── mirrors pvr-activity / pvr-subactivity ───── */
.pra-act-group {
  background: #fafaf8;
  border: 1.5px solid #e7e5e4;
  border-radius: 12px;
  overflow: hidden;
}
.pra-act-group--sub {
  border-top: none;
  border-radius: 0 0 12px 12px;
}

/* Activity heading — mirrors pvr-activity__heading */
.pra-act-heading {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 14px 10px;
  background: white;
  border-bottom: 1px solid #f5f5f4;
}
.pra-act-heading__index {
  font-family: "JetBrains Mono", monospace;
  font-size: 10px;
  font-weight: 700;
  color: #a8a29e;
  background: #f5f5f4;
  padding: 3px 6px;
  border-radius: 5px;
  flex-shrink: 0;
  margin-top: 2px;
}
.pra-act-heading__name {
  font-size: 13px;
  font-weight: 700;
  color: #1c1917;
  letter-spacing: -0.01em;
}
.pra-act-heading__desc {
  font-size: 11px;
  color: #a8a29e;
  margin-top: 2px;
}

/* Sub-activity heading — mirrors pvr-subactivity__heading */
.pra-sub-heading {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 14px 10px;
  border-bottom: 1px dashed #fed7aa;
  margin-bottom: 0;
  background: white;
}
.pra-sub-heading__line {
  width: 14px;
  height: 1px;
  background: #f59e0b;
  flex-shrink: 0;
}
.pra-sub-heading__index {
  font-family: "JetBrains Mono", monospace;
  font-size: 10px;
  color: #d97706;
  background: #fef3c7;
  padding: 2px 6px;
  border-radius: 4px;
  flex-shrink: 0;
}
.pra-sub-heading__name {
  font-size: 12px;
  font-weight: 600;
  color: #78350f;
}

/* ── KPI SLOT + CARD ─── mirrors pvr-kpi-slot / pvr-kpi-card ────── */
.pra-kpi-slot {
  padding: 6px 12px 6px;
}

.pra-kpi-card {
  background: white;
  border: 1.5px solid #e7e5e4;
  border-radius: 14px;
  overflow: hidden;
  transition: box-shadow 0.2s, border-color 0.2s;
}
.pra-kpi-card:hover {
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.07);
}

